import json,sys,urllib.request
def search(q):
    body={"query":q,"return_type":"entry","request_options":{"paginate":{"start":0,"rows":15},"sort":[{"sort_by":"rcsb_entry_info.resolution_combined","direction":"asc"}]}}
    r=urllib.request.Request("https://search.rcsb.org/rcsbsearch/v2/query",data=json.dumps(body).encode(),headers={"Content-Type":"application/json"})
    return [x["identifier"] for x in json.load(urllib.request.urlopen(r,timeout=30)).get("result_set",[])]
def tq(t,extra=None):
    nodes=[{"type":"terminal","service":"full_text","parameters":{"value":t}},
           {"type":"terminal","service":"text","parameters":{"attribute":"exptl.method","operator":"exact_match","value":"X-RAY DIFFRACTION"}},
           {"type":"terminal","service":"text","parameters":{"attribute":"rcsb_entry_info.nonpolymer_entity_count","operator":"greater","value":0}}]
    return {"type":"group","logical_operator":"and","nodes":nodes}
for t in sys.argv[1:]:
    print(t, search(tq(t)))
EOF
